// Shared life core: general life insurance, annuity and Social Security questions used by every
// state. Topic letters map to the practice test's colored parts. Never reuse or renumber an ID.
LHEP.bank({
  name: "Shared life core",
  topics: {
    L1: { name: "Insurers and how they are organized", part: "A" },
    L2: { name: "Risk, loss and hazards", part: "A" },
    L3: { name: "Contracts, agency and negligence", part: "A" },
    L6: { name: "Underwriting, the application and delivery", part: "A" },
    L10: { name: "Producer ethics and unfair practices", part: "A" },
    L4: { name: "Life insurance policies", part: "B" },
    L5: { name: "Riders, provisions and options", part: "B" },
    L7: { name: "Annuities", part: "C" },
    L8: { name: "Business uses, group life and retirement plans", part: "C" },
    L9: { name: "Social Security", part: "C" }
  },
  sources: {
    irc72: { label: "26 U.S.C. § 72", url: "https://www.law.cornell.edu/uscode/text/26/72" },
    irc1035: { label: "26 U.S.C. § 1035", url: "https://www.law.cornell.edu/uscode/text/26/1035" },
    finra: { label: "FINRA Series 6", url: "https://www.finra.org/registration-exams-ce/qualification-exams/series6" }
  }
}, ({ mc, tf, sa }) => {
  mc("L001", "L1", "Which type of insurer issues participating policies?", ["Mutual company", "Stock company", "Alien insurer", "Reciprocal exchange"], "A", "Mutual companies are owned by policyholders and issue participating policies.");
  mc("L002", "L1", "An insurer incorporated in Ohio that sells policies in another state is, in that other state, a(n):", ["Domestic insurer", "Alien insurer", "Nonadmitted insurer", "Foreign insurer"], "D", "Foreign means incorporated in another US state. Domestic is this state; alien is outside the US.");
  mc("L003", "L1", "Under a reinsurance agreement, which company stays responsible to the policyowner?", ["The reinsurer", "The state guaranty association", "The assuming insurer", "The ceding insurer"], "D", "The ceding (original) insurer stays responsible to the client.");
  mc("L004", "L1", "Reinsurance that applies automatically to a broad class of risks is:", ["Treaty", "Facultative", "Surplus lines", "Retention"], "A", "Treaty is broad and automatic; facultative is case by case.");
  mc("L005", "L1", "Who is NOT licensed to sell insurance but introduces clients to a producer?", ["Broker", "Agent", "Field underwriter", "Solicitor"], "D", "Solicitors can't sell; they refer clients to a producer.");
  mc("L006", "L1", "The McCarran-Ferguson Act of 1945 established that:", ["The federal government regulates insurance", "Agents need a federal license", "States regulate the business of insurance", "All insurers must be mutual companies"], "C", "McCarran-Ferguson left insurance regulation to the states.");
  mc("L007", "L2", "Which of these is an insurable risk?", ["Buying stock", "A home burning down", "Betting on a game", "Opening a new business"], "B", "Only pure risk (chance of loss, no gain) is insurable. The others are speculative.");
  mc("L008", "L2", "A policyholder stops locking their car because “insurance will cover it.” This is:", ["Moral hazard", "Physical hazard", "Speculative risk", "Morale hazard"], "D", "Morale hazard is carelessness because you're insured. Moral hazard is intentional dishonesty.");
  mc("L009", "L2", "Frayed electrical wiring in a building is a:", ["Physical hazard", "Moral hazard", "Morale hazard", "Peril"], "A", "A physical hazard is a tangible condition you can see or measure.");
  mc("L010", "L2", "Buying an insurance policy is which risk management method?", ["Avoidance", "Transfer", "Retention", "Reduction"], "B", "Insurance transfers risk to another party by contract.");
  mc("L011", "L2", "Choosing a higher deductible to lower the premium is an example of risk:", ["Sharing", "Avoidance", "Transfer", "Retention"], "D", "A deductible is risk you deliberately keep.");
  mc("L012", "L2", "According to the law of large numbers:", ["As the number of insureds increases, the number of losses decreases", "Losses can be eliminated with enough insureds", "Every insured pays the same premium", "The larger the group of similar exposure units, the more predictable losses become"], "D", "The law of large numbers improves predictability. The first choice is the classic false statement.");
  mc("L013", "L2", "Adverse selection refers to:", ["Higher-risk people being more likely to seek insurance", "An insurer declining applicants who are higher risks", "Spreading the risk of loss among many similar people", "An agent steering applicants to one particular insurer"], "A", "Higher-risk people seek coverage more, so claims run higher than expected. Underwriting guards against it.");
  mc("L014", "L2", "Which is an exception to the principle of indemnity?", ["Actual cash value property coverage", "Life insurance", "Liability coverage", "Medical expense reimbursement"], "B", "Life insurance pays a stated amount, not a measured loss.");
  mc("L015", "L3", "Which is NOT one of the four elements of a legal contract?", ["Warranty", "Consideration", "Competent parties", "Legal purpose"], "A", "The elements are CLOC: Competent parties, Legal purpose, Offer and acceptance, Consideration.");
  mc("L016", "L3", "A contract in which one party may receive much more than it paid in is:", ["Unilateral", "Conditional", "Aleatory", "Adhesive"], "C", "Aleatory means an unequal exchange of value.");
  mc("L017", "L3", "The insurer writes the policy, the insured must take it as written, and unclear wording is read in the insured's favor. This describes a contract of:", ["Indemnity", "Adhesion", "Utmost good faith", "Bilateral agreement"], "B", "That's a contract of adhesion: take it or leave it, with ambiguities favoring the insured.");
  mc("L018", "L3", "Statements on an application that the applicant believes to be true are:", ["Warranties", "Concealments", "Estoppels", "Representations"], "D", "Representations are believed true; warranties are guaranteed true.");
  mc("L019", "L3", "An agent forgets to submit a client's application. This is:", ["Simple negligence", "Gross negligence", "Willful and wanton negligence", "Fraud"], "A", "A one-time failure to act reasonably is simple negligence.");
  mc("L020", "L3", "Authority that the public reasonably believes an agent has, based on the insurer's actions, is:", ["Express", "Implied", "Fiduciary", "Apparent"], "D", "Apparent authority comes from the public's reasonable belief. Express is written; implied is needed to do the express duties.");
  mc("L021", "L4", "Which policy gives pure, temporary protection at the lowest premium for a set period?", ["Whole life", "Universal life", "Limited-pay life", "Level term"], "D", "Level term is temporary, pure protection at the lowest premium.");
  mc("L022", "L4", "Credit life insurance is usually written as:", ["Decreasing term", "Level term", "Whole life", "Variable life"], "A", "Credit life is decreasing term that shrinks with the debt.");
  mc("L023", "L4", "A term policy is converted to whole life, and the new premium is based on the insured's age at conversion. This is:", ["Original age", "Issue age", "Attained age", "Age 65"], "C", "Attained age is the insured's age at conversion, so the premium is higher.");
  mc("L024", "L4", "Compared with straight whole life, a 20-pay life policy:", ["Has lower annual premiums", "Builds cash value faster", "Expires after 20 years", "Has no cash value"], "B", "Premiums are packed into 20 years, so cash value builds faster. The premiums are higher.");
  mc("L025", "L4", "A policy funded so fast that it fails the IRS 7-pay test becomes a:", ["Modified endowment contract (MEC)", "Variable universal life policy", "Single premium endowment policy", "Indeterminate premium policy"], "A", "Failing the 7-pay test makes it a MEC. Loans and withdrawals become taxable.");
  mc("L026", "L4", "In universal life, the pure insurance protection above the cash value is called the:", ["Loading", "Reserve", "Surrender charge", "Corridor"], "D", "The corridor is the pure protection above the cash value.");
  mc("L027", "L4", "Which policy's cash value and death benefit rise and fall with separate-account investments?", ["Indexed universal life", "Variable life", "Adjustable life", "Limited-pay life"], "B", "Variable life follows its separate-account (equity) investments, and the owner bears the risk.");
  mc("L028", "L4", "A survivorship (joint and survivor) policy pays the death benefit:", ["At the first death", "At each death", "When both insureds reach age 100", "At the second death"], "D", "Survivorship, or second-to-die, pays at the last death.");
  mc("L029", "L5", "A policyowner transfers all ownership rights to another person. This is:", ["Collateral assignment", "Irrevocable beneficiary designation", "Viatical settlement", "Absolute assignment"], "D", "An absolute assignment transfers full ownership and control.");
  mc("L030", "L5", "A terminally ill insured expected to live 1–2 years wants part of the death benefit now. Which rider allows this?", ["Accelerated benefits", "Accidental death benefit", "Waiver of premium", "Payor benefit"], "A", "Accelerated benefits pay part of the death benefit early for a terminal illness.");
  mc("L031", "L5", "The payor benefit rider is most often attached to a:", ["Group term policy", "Credit life policy", "Juvenile policy", "Annuity"], "C", "The payor rider goes on juvenile policies and waives premiums if the payor dies or is disabled.");
  mc("L032", "L5", "Under the automatic premium loan provision, an unpaid premium is:", ["Waived permanently once the grace period ends", "Paid by the agent and billed to the owner later", "Deducted only from the death benefit at claim time", "Borrowed from the cash value when the grace period ends"], "D", "The automatic premium loan borrows the premium from cash value when the grace period ends.");
  mc("L033", "L5", "Which is NOT a dividend option?", ["Paid-up additions", "Extended term", "One-year term", "Reduction of premium"], "B", "Extended term is a nonforfeiture option. Dividend options are CRAPO: Cash, Reduction of premium, Accumulate at interest, Paid-up additions, One-year term.");
  mc("L034", "L5", "A policyowner stops paying premiums, and the cash value buys term coverage for the full face amount for as long as it lasts. This nonforfeiture option is:", ["Extended term", "Reduced paid-up", "Cash surrender", "Automatic premium loan"], "A", "Extended term keeps the full face amount for a shorter time. Reduced paid-up keeps coverage for life at a smaller amount.");
  mc("L035", "L5", "After a life policy has been in force for 2 years, the insurer generally can't void it for misstatements on the application. This is the:", ["Entire contract provision", "Suicide clause", "Reinstatement provision", "Incontestability clause"], "D", "The incontestability clause applies after 2 years.");
  mc("L036", "L5", "An insured dies by suicide 14 months after the policy was issued. The insurer will:", ["Pay the full face amount", "Refund the premiums paid", "Pay nothing at all", "Pay half the face amount"], "B", "Suicide within 2 years of issue means premiums are refunded, with no death benefit.");
  mc("L037", "L5", "Under the entire contract provision, the contract consists of:", ["The policy alone, without the application", "The application and the agent's report", "The policy plus the agent's sales notes", "The policy, the application and any endorsements"], "D", "The policy, the application and the endorsements make up the entire contract.");
  mc("L038", "L5", "The insured and the primary beneficiary die in the same accident and no one can tell who died first. With no common disaster clause, the Uniform Simultaneous Death Act pays the proceeds:", ["As if the insured survived, so to the contingent beneficiary or estate", "As if the beneficiary survived, so to the beneficiary's estate", "Split equally between the insured's and beneficiary's estates", "To the state as unclaimed property, since no one survived"], "A", "The act presumes the insured outlived the beneficiary.");
  mc("L039", "L4", "Which is NOT a factor in calculating a life insurance premium?", ["Mortality", "Morbidity", "Interest", "Expense"], "B", "Life premiums use mortality, interest and expense. Morbidity (illness rates) is for health insurance.");
  mc("L040", "L4", "Gross premium equals:", ["Net premium minus the dividends expected", "Mortality cost minus interest earnings", "Net premium plus loading for expenses", "Net premium plus the policy's cash value"], "C", "Gross premium = net premium + loading. Net single premium = mortality − interest.");
  mc("L041", "L5", "Life insurance death proceeds paid in a lump sum to a beneficiary are generally:", ["Fully taxable as income", "Taxed as a capital gain", "Taxable only above $255", "Free of income tax"], "D", "Lump-sum death proceeds are income-tax free. Interest earned on proceeds held by the insurer is taxable.");
  mc("L042", "L5", "A revocable beneficiary can be changed by the policyowner:", ["At any time", "Only with the beneficiary's consent", "Only on the policy anniversary", "Never"], "A", "A revocable beneficiary can be changed at any time. An irrevocable one must consent.");
  mc("L043", "L4", "Level premiums are possible for whole life because:", ["The insurer guarantees dividends that offset rising costs", "Early premiums exceed the cost of protection, building a reserve", "Premiums rise each year, but the increases are refunded", "Cash value is paid out each year to cover the extra cost"], "B", "Overpaying in the early years builds the reserve that keeps later premiums level.");
  mc("L044", "L4", "A client wants lifetime coverage but wants to finish paying premiums before retirement. The best fit is:", ["Decreasing term", "Renewable term", "Credit life", "Limited-pay life"], "D", "Limited-pay life gives lifetime coverage with a shorter payment period.");
  mc("L045", "L3", "Investors buy a policy on a stranger's life (STOLI). Which contract element does this violate?", ["Consideration (premium and promises)", "Offer and acceptance (the application)", "Competent parties (age and sanity)", "Legal purpose (insurable interest)"], "D", "Without insurable interest, the contract has no legal purpose.");
  mc("L046", "L6", "The agent who starts the underwriting process is called the:", ["Field underwriter", "Actuary", "Claims adjuster", "Service representative"], "A", "The agent is the field underwriter.");
  mc("L047", "L6", "A report on the applicant from their own doctor is a(n):", ["Medical Information Bureau (MIB) report", "Inspection (consumer investigative) report", "Attending physician statement (APS)", "Paramedical examiner's report"], "C", "An APS comes from the applicant's own doctor. The MIB shares medical data among insurers.");
  mc("L048", "L6", "An applicant pays the first premium and receives a conditional receipt. Coverage begins:", ["When the policy is delivered and the premium is collected", "On the application (or exam) date, if they qualify as applied for", "Immediately, whatever the underwriting decision turns out to be", "When the agent signs and sends the application to the insurer"], "B", "Conditional receipt coverage dates back only if the applicant qualifies as applied for.");
  mc("L049", "L6", "Which receipt gives immediate coverage until the insurer accepts or rejects the application?", ["Conditional receipt", "Premium receipt", "Policy summary", "Binding receipt"], "D", "A binding receipt gives immediate temporary coverage. It's used sparingly in life insurance.");
  mc("L050", "L6", "No premium was paid with the application. Coverage begins:", ["On the application date, as with a conditional receipt", "As soon as underwriting approves the application", "On the date the applicant completes the medical exam", "When the policy is delivered and the first premium is paid"], "D", "No premium means no coverage until delivery and payment in full.");
  mc("L051", "L6", "For life insurance, insurable interest must exist:", ["At the time of application", "At the time of death", "At both application and death", "Only when a claim is filed"], "A", "For life insurance, insurable interest is needed at application only.");
  mc("L052", "L1", "Under the Fair Credit Reporting Act, an applicant must be:", ["Given a free copy of their MIB file with the policy", "Told that a consumer report may be requested", "Allowed to choose which underwriter reviews them", "Refunded any premium if a report is ordered"], "B", "The FCRA requires notice that a consumer report may be requested.");
  mc("L053", "L6", "An applicant who is a better-than-average risk is classified as:", ["Standard", "Substandard", "Preferred", "Rated"], "C", "Preferred is better than average; standard is average; substandard (rated) is worse.");
  mc("L054", "L6", "Unless a question says otherwise, you should assume:", ["The insured and the owner are different people", "The beneficiary is the applicant", "The agent pays the premium", "The owner, applicant, payor and insured are the same person"], "D", "On the exam, the owner, applicant, payor and insured are the same person unless stated.");
  mc("L055", "L7", "Annuities protect against the risk of:", ["Dying too soon", "Disability", "Liability claims", "Living too long"], "D", "Annuities cover the risk of outliving your money.");
  mc("L056", "L7", "During the accumulation phase of an annuity, who holds the contract rights?", ["The contract owner", "The annuitant", "The beneficiary", "The insurer"], "A", "The contract owner holds the rights during accumulation. The annuitant receives the payout.");
  mc("L057", "L7", "A single premium immediate annuity (SPIA) begins payments within:", ["30 days", "6 months", "5 years", "12 months"], "D", "A SPIA starts paying within 12 months.");
  mc("L058", "L7", "An annuity whose interest is linked to a stock market index, but which is not a variable product, is a(n):", ["Variable annuity", "Equity-indexed annuity", "Market value adjusted annuity", "Flexible premium deferred annuity"], "B", "Equity-indexed annuities are fixed products with interest tied to an index.");
  mc("L059", "L7", "Qualified retirement plans are funded with:", ["Pre-tax dollars", "After-tax dollars", "Employer money only", "Life insurance cash value only"], "A", "Qualified plans use pre-tax dollars. Non-qualified annuities use after-tax dollars.");
  mc("L060", "L8", "A 403(b) tax-sheltered annuity is available to employees of:", ["Any for-profit corporation with 20 or more employees", "Sole proprietors and their family members", "Public schools and 501(c)(3) nonprofits", "Federal agencies and the armed forces"], "C", "403(b) plans are for public schools and 501(c)(3) nonprofits.");
  mc("L061", "L8", "A Keogh (HR-10) plan is for:", ["Employees of nonprofit hospitals and schools", "Large corporations with union employees", "State and local government employees", "The self-employed, who must cover eligible employees"], "D", "Keogh plans are for the self-employed and must include eligible employees.");
  mc("L062", "L8", "Under ERISA, an employee is always 100% vested in:", ["Their own contributions", "Employer contributions", "Profit-sharing contributions", "Nothing until 5 years of service"], "A", "Your own contributions are always 100% vested. Employer money follows a vesting schedule.");
  mc("L063", "L8", "On an indirect rollover from a qualified profit-sharing plan, the plan must withhold:", ["10%", "25%", "20%", "Nothing"], "C", "20% is withheld for income tax on an indirect rollover.");
  mc("L064", "L8", "A person 73 or older who fails to take a required minimum distribution owes an IRS excise tax of:", ["10%", "25%", "20%", "50%"], "B", "The penalty for a missed RMD is 25%.");
  mc("L065", "L9", "A self-employed person pays FICA tax of:", ["6.2%", "7.65%", "12.4%", "15.3%"], "D", "The self-employed pay both halves: 7.65% + 7.65% = 15.3%.");
  mc("L066", "L9", "Fully insured status for Social Security requires:", ["40 credits (about 10 years of work)", "6 credits", "20 credits", "6 credits in the last 13 quarters"], "A", "Fully insured takes 40 credits. Six credits in the last 13 quarters is currently insured.");
  mc("L067", "L9", "The Social Security blackout period:", ["Runs from the youngest child's 18th birthday to the spouse's 65th", "Runs from the youngest child's 16th birthday to the spouse's 60th", "Is the 5-month waiting period before disability benefits", "Begins when the surviving spouse turns 60 and lasts 2 years"], "B", "The blackout runs from the youngest child's 16th birthday to the surviving spouse's 60th.");
  mc("L068", "L9", "The waiting period for Social Security disability benefits is:", ["30 days", "90 days", "12 months", "5 months"], "D", "Social Security disability has a 5-month waiting period.");
  mc("L069", "L8", "In key person life insurance, the owner and beneficiary is:", ["The key employee", "The key employee's family", "The business", "The insurer"], "C", "The business owns the policy, pays for it and is the beneficiary. The key employee is the insured.");
  mc("L070", "L8", "An employee leaving a group life plan can convert to individual whole life without proof of insurability within:", ["31 days", "10 days", "6 months", "1 year"], "A", "Group conversion is within 31 days, at attained age, with no medical exam.");
  mc("L071", "L10", "An agent misrepresents a client's current policy to get them to drop it and buy a new one. This is:", ["Rebating", "Controlled business", "Twisting", "Fair replacement"], "C", "Misrepresenting to replace a policy is twisting.");
  mc("L072", "L10", "An agent deposits client premiums in their personal checking account. This is:", ["Rebating", "Defamation", "Sliding", "Commingling"], "D", "Mixing premiums with personal funds is commingling.");
  mc("L073", "L10", "Which is permitted (fair) discrimination?", ["Charging smokers more than nonsmokers", "Charging more based on race", "Charging different rates to people in the same risk class", "Declining an applicant because of marital status"], "A", "Smoking is a legitimate, risk-based underwriting factor.");
  tf("L074", "L2", "Speculative risks are insurable.", false, "Only pure risks are insurable.");
  tf("L075", "L2", "Every accident is an occurrence, but not every occurrence is an accident.", true, "An occurrence includes gradual events; an accident is sudden.");
  tf("L076", "L3", "Insurance contracts are bilateral.", false, "Insurance contracts are unilateral: only the insurer makes an enforceable promise.");
  tf("L077", "L6", "For life insurance, insurable interest must exist at the time of the insured's death.", false, "It must exist at the time of application.");
  tf("L078", "L5", "Death proceeds are income-tax free, but interest earned on proceeds held by the insurer is taxable.", true, "Interest on retained proceeds is taxable.");
  tf("L079", "L9", "The Medicare portion of FICA has a wage cap.", false, "Social Security has the wage cap; Medicare doesn't.");
  tf("L080", "L4", "Morbidity is one of the factors used to price life insurance.", false, "Life premiums use mortality, interest and expense.");
  tf("L081", "L1", "Dividends on a participating policy are guaranteed.", false, "Dividends are declared by the insurer and never guaranteed.");
  tf("L082", "L1", "A domestic insurer is one incorporated in this state.", true, "Domestic means incorporated in this state.");
  tf("L083", "L2", "As the number of insureds increases, the number of losses decreases.", false, "Losses become more predictable, not fewer.");
  sa("L084", "L5", "Name the five dividend options.", "CRAPO: Cash, Reduction of premium, Accumulate at interest, Paid-up additions, One-year term.");
  sa("L085", "L3", "Name the four elements of a legal contract.", "CLOC: Competent parties, Legal purpose, Offer and acceptance, Consideration.");
  sa("L086", "L6", "Explain the difference between a conditional receipt and a binding receipt.", "A conditional receipt dates coverage back to the application (or exam) only if the applicant qualifies as applied for. A binding receipt gives immediate coverage until the insurer decides, and is used sparingly in life insurance.");
  sa("L087", "L8", "Tom is 80% vested in $10,000 of employer contributions when he leaves his job. How much of the employer money does he keep, and how much does he forfeit?", "He keeps $8,000 and forfeits $2,000. His own contributions are always 100% his.");
  sa("L088", "L2", "Explain the difference between moral and morale hazard, with one example of each.", "Moral hazard is intentional dishonesty, such as arson or faking a claim. Morale hazard is carelessness because you're insured, such as leaving the car unlocked.");
  mc("L089", "L3", "A proposed insured asks a healthier friend to take the medical exam in their place. This is:", ["Adverse selection", "Impersonation", "Twisting", "Rebating"], "B", "Someone posing as the applicant is impersonation, a form of fraud that lets the insurer void the contract.");
  mc("L090", "L3", "An applicant deliberately doesn't mention a heart condition the insurer would need to know about. This is:", ["Concealment", "Estoppel", "Waiver", "A warranty"], "A", "Concealment is withholding a material fact. It can let the insurer void the policy.");
  mc("L091", "L2", "Which group gives an insurer the most reliable prediction of losses?", ["10 similar homes", "One very expensive home", "10,000 homes of every age, size and type mixed together", "10,000 similar homes"], "D", "The law of large numbers works best with many exposure units that are similar (homogeneous).");
  mc("L092", "L4", "A universal life policy that pays the face amount plus the cash value uses which death benefit option?", ["Option A (level)", "Option B (increasing)", "Return of premium option", "Corridor option"], "B", "Option A pays a level face amount that includes the cash value. Option B pays the face amount plus the cash value, so the benefit grows.");
  mc("L093", "L4", "In universal life, the premium the insurer suggests paying to keep the policy in force as planned is the:", ["Target premium", "Gross premium", "Minimum deposit", "Loading"], "A", "The target premium is the recommended amount; paying less can shrink the cash value or lapse the policy.");
  mc("L094", "L4", "Universal life is called “unbundled” because:", ["It has no cash value, only pure protection", "Its riders are sold as separate policies", "Its dividends are paid separately from premiums", "It shows mortality, expense and interest separately"], "D", "The policy shows each part of the cost and the interest credited separately, so the owner can see where the money goes.");
  mc("L095", "L4", "An endowment policy pays the face amount:", ["Only if the insured dies before the maturity date", "At death or at maturity, whichever comes first", "Only at maturity, if the insured is still alive", "In monthly installments for the insured's life"], "B", "An endowment pays at death during the term or, if the insured is still alive, at the maturity date.");
  mc("L096", "L4", "A whole life policy with a lower premium for the first few years, then a higher level premium for life, is a:", ["Modified premium policy", "Single premium policy", "Limited-pay policy", "Decreasing term policy"], "A", "Modified premium whole life starts low, then steps up once to a level premium. Graded premium rises gradually each year before leveling.");
  mc("L097", "L4", "A juvenile policy whose face amount increases automatically at a set age, such as 21, with no increase in premium and no proof of insurability, is a:", ["Payor benefit policy", "Family maintenance policy", "Guaranteed insurability rider", "Jumping juvenile policy"], "D", "A jumping juvenile policy steps the face amount up, often fivefold, at a set age.");
  mc("L098", "L5", "The insured dies during the grace period with a premium still unpaid. The insurer:", ["Pays the death benefit minus the overdue premium", "Pays nothing, since the premium wasn't paid on time", "Pays only the cash value, not the face amount", "Refunds the premiums paid instead of the benefit"], "A", "Coverage continues during the grace period; the unpaid premium is deducted from the death benefit.");
  mc("L099", "L5", "The insured understated their age on the application. At death, the insurer will:", ["Deny the claim because of a material misrepresentation", "Pay the full face amount and bill the estate for the difference", "Pay what the premiums would have bought at the correct age", "Refund all premiums paid, plus interest, instead of paying"], "C", "The misstatement of age provision requires an equitable adjustment of benefits or premiums.");
  mc("L100", "L5", "A war exclusion that denies the death benefit only when death is caused by war is the:", ["Status type", "Aviation type", "Suicide type", "Results type"], "D", "Results type excludes deaths caused by war. Status type excludes any death while in military service, whatever the cause.");
  mc("L101", "L5", "A policyowner pledges their life policy as security for a bank loan. The lender is repaid first from the proceeds and the rest goes to the beneficiary. This is:", ["Absolute assignment", "Collateral assignment", "Irrevocable beneficiary designation", "Viatical settlement"], "B", "A collateral assignment is partial and temporary. An absolute assignment transfers ownership completely.");
  mc("L102", "L5", "Which rider lets the insured buy more coverage at set ages or events, like marriage or a birth, without proving insurability?", ["Guaranteed insurability", "Waiver of premium", "Cost of living", "Accelerated benefits"], "A", "The guaranteed insurability rider (or option) allows future purchases without new evidence of insurability.");
  mc("L103", "L5", "Which settlement option pays the beneficiary a set dollar amount each period until the proceeds and interest run out?", ["Interest only", "Fixed period", "Fixed amount", "Life income"], "C", "Fixed amount sets the payment size. Fixed period sets the length of time. Interest only keeps the principal with the insurer; life income pays for life.");
  mc("L104", "L5", "A whole life policy lapses with cash value, and the owner never chose a nonforfeiture option. The option that usually applies automatically is:", ["Cash surrender", "Reduced paid-up", "Extended term", "Automatic premium loan"], "C", "Extended term is the usual automatic option when no election is made.");
  mc("L105", "L5", "An insurer may delay paying a cash surrender value, or a loan not used to pay premiums, for up to:", ["30 days", "60 days", "6 months", "1 year"], "C", "Policies let the insurer defer these payments for up to 6 months.");
  mc("L106", "L6", "The premium wasn't paid with the application. When delivering the policy, the agent should collect the premium and:", ["A signed statement of continued good health", "A new medical exam done at the time of delivery", "A binding receipt signed by the applicant", "A copy of the buyer's latest tax return"], "A", "On a nonprepaid policy, the agent collects the first premium and a statement that the insured's health hasn't changed.");
  mc("L107", "L6", "An insurer issues a policy with a higher premium than the applicant applied for. Legally, this is:", ["Acceptance of the applicant's offer, so coverage starts", "A counteroffer the applicant must accept for coverage to begin", "A binding receipt that covers the applicant until delivery", "A rescission that cancels the original application"], "B", "A policy issued other than as applied for is a counteroffer. The applicant accepts it, usually by signing and paying, at delivery.");
  mc("L108", "L6", "An applicant submits a completed application with the first premium. Who has made the offer?", ["The agent", "The insurer", "The applicant", "The underwriter"], "C", "The application plus the premium is the applicant's offer. The insurer accepts by issuing the policy as applied for.");
  mc("L109", "L6", "An applicant gives a wrong answer on a paper application. The agent should:", ["Erase it and write in the correct answer neatly", "Leave it and tell the underwriter about it by phone", "Cross it out, correct it and have the applicant initial it", "Ignore it if it doesn't seem important to underwriting"], "C", "Corrections are made openly and initialed by the applicant, never erased or whited out.");
  mc("L110", "L7", "Which annuity payout option gives the highest monthly income for one person but stops at death with nothing left for a beneficiary?", ["Life with period certain", "Straight (pure) life", "Cash refund", "Joint and survivor"], "B", "Straight life pays the most per month because nothing is guaranteed after the annuitant dies.");
  mc("L111", "L7", "An annuitant chose life income with a 10-year period certain and dies after 4 years. The beneficiary receives:", ["Nothing", "A lump sum of the premium paid", "Payments for the remaining 6 years", "Payments for 10 more years"], "C", "The period certain guarantees payments for at least 10 years in total.");
  mc("L112", "L7", "A cash refund annuity guarantees that:", ["Payments never decrease, even if interest rates fall", "The buyer can cancel within 15 days for a full refund", "Payments rise each year to keep up with inflation", "The unrecovered premium goes to a beneficiary in a lump sum"], "D", "If the annuitant dies before receiving what they paid in, the difference goes to the beneficiary. An installment refund pays it out in installments instead.");
  mc("L113", "L7", "A married couple wants income that continues as long as either spouse is alive. They should choose a:", ["Straight life annuity", "Period certain annuity", "Joint and survivor annuity", "Cash refund annuity"], "C", "A joint and survivor annuity keeps paying until the second death.");
  mc("L114", "L7", "A 52-year-old takes $10,000 of earnings out of a deferred annuity. On top of income tax, federal law adds a penalty of:", ["5%", "10%", "20%", "Nothing"], "B", "The additional tax is 10% before age 59½, unless an exception applies, such as death, disability or substantially equal periodic payments.", "irc72");
  mc("L115", "L7", "Withdrawals from a non-qualified deferred annuity before annuitization are taxed:", ["As capital gains", "Principal first, tax-free until the basis is used up", "Not at all", "Earnings first, as ordinary income"], "D", "Earnings come out first and are taxed as ordinary income. MECs are taxed the same way.", "irc72");
  mc("L116", "L7", "Which exchange can be done tax-free under IRC Section 1035?", ["Life insurance to an annuity", "Annuity to life insurance", "Life insurance to a mutual fund", "Annuity to a certificate of deposit"], "A", "Life can go to life, endowment or annuity, and annuity can go to annuity. An annuity can't go to life insurance tax-free.", "irc1035");
  mc("L117", "L8", "In a buy-sell agreement, each business owner buys a policy on each of the other owners. This is a:", ["Entity (stock redemption) plan", "Key person plan", "Cross-purchase plan", "Split-dollar plan"], "C", "In a cross-purchase plan the owners insure each other. In an entity plan the business owns a policy on each owner.");
  mc("L118", "L8", "A small business wants to fund retirement through contributions the employer makes to each employee's own IRA, with very simple paperwork. Which plan fits?", ["SEP (Simplified Employee Pension)", "Keogh (HR-10) retirement plan", "403(b) tax-sheltered annuity", "Defined benefit pension plan"], "A", "A SEP puts employer contributions into employees' IRAs with little administration.");
  mc("L119", "L4", "To sell variable annuities or variable life insurance, a producer needs a life license and:", ["An adjuster license from the state", "A property and casualty producer license", "A CPA license or financial planning certificate", "FINRA securities registration, such as the Series 6"], "D", "Variable products are securities, so the seller must also hold a FINRA registration like the Series 6.", "finra");
  tf("L120", "L7", "An annuity can be exchanged tax-free for a life insurance policy under IRC Section 1035.", false, "Annuity to annuity is allowed. Annuity to life insurance is not.", "irc1035");
  sa("L121", "L5", "Besides taking a lump sum, name the four common settlement options for life insurance proceeds.", "Interest only, fixed period, fixed amount, and life income (single or joint).");

  // Exam-style questions added 2026-11-11, following the NC Life content outline (March 2024)
  // Types of individual life insurance (L4)
  mc("L122", "L4", "Which statement about term life insurance is NOT true?", ["It covers the insured for a set period", "It generally builds no cash value", "At the same issue age, it costs less per $1,000 than whole life", "It pays the face amount if the insured outlives the term"], "D", "Term pays only if the insured dies during the term. If the insured outlives it, coverage simply ends.");
  mc("L123", "L4", "An annually renewable term (ART) policy:", ["Keeps the same premium for the full term, but needs new evidence each year", "Can be renewed each year without evidence of insurability, at a higher premium each time", "Can be renewed each year only if the insured passes a new medical exam", "Builds cash value each year that pays the rising renewal premiums"], "B", "ART renews every year with no proof of insurability. The premium rises each year with the insured's age.");
  mc("L124", "L4", "When a renewable term policy is renewed, the new premium is based on the insured's:", ["Age when the policy was first issued", "Health at the time of renewal", "Attained age at renewal", "Occupation at renewal"], "C", "Renewal needs no evidence of insurability, but the premium is figured at the insured's attained (current) age.");
  mc("L125", "L4", "Insurers usually stop allowing term renewals at a set age, such as 70 or 80, mainly to guard against:", ["Adverse selection", "Inflation", "Rising interest rates", "Rebating"], "A", "People in poor health are the most likely to keep renewing at older ages, so insurers cap renewals.");
  mc("L126", "L4", "Maria converts her term policy to whole life using her original age instead of her attained age. An original-age conversion usually requires her to:", ["Pay nothing extra, since conversion always uses the original-age rate", "Take a new medical exam, since original-age conversion needs proof of insurability", "Pay a lump sum covering the premium difference, plus interest, back to the issue date", "Drop all of her riders and accept a lower face amount than the term policy"], "C", "Original-age (retroactive) conversion gives the lower premium of the younger age, so the owner pays the difference for the past years. Attained-age conversion needs no back payment but costs more going forward.");
  mc("L127", "L4", "Which is true of converting a term policy to permanent insurance during the conversion period?", ["No evidence of insurability is required", "The insured must pass a medical exam", "Conversion is allowed only after the term ends", "The new face amount must be larger than the term face amount"], "A", "Convertibility guarantees the right to switch to permanent coverage without proving insurability, as long as it's done within the conversion period.");
  mc("L128", "L4", "A decreasing term policy usually has:", ["A premium that drops each year", "A level premium while the face amount drops", "A cash value that grows each year", "A face amount that drops only at renewal"], "B", "The face amount falls on a schedule, but the premium normally stays level. Premiums often end a few years before the term does.");
  mc("L129", "L4", "A policy pays the face amount plus all premiums paid if the insured dies within 20 years. This return-of-premium feature is usually built by adding:", ["Decreasing term that shrinks as premiums are paid", "Paid-up additions bought with each year's premium", "An accidental death benefit equal to the premiums", "Increasing term equal to the premiums paid"], "D", "The return-of-premium benefit is increasing term coverage that grows as premiums are paid.");
  mc("L130", "L4", "A whole life policy that pays the face amount plus the cash value at death does it by adding:", ["Increasing term equal to the cash value", "Decreasing term equal to the cash value", "An accidental death rider equal to the face", "A waiver of premium rider tied to the cash value"], "A", "Normally the cash value is part of the face amount. To pay both, the insurer adds increasing term that keeps pace with the cash value.");
  mc("L131", "L4", "Which statement about straight whole life is true?", ["The premium rises every few years as the insured gets older", "The cash value equals the face amount at maturity (age 100, or 121 under newer tables)", "Coverage ends at age 65 unless the owner converts it to a new policy", "It builds no cash value until it has been in force for 20 years"], "B", "Whole life has a level premium and endows (cash value equals the face amount) at maturity, age 100 or 121 depending on the mortality table.");
  mc("L132", "L4", "Whole life insurance has all of these features EXCEPT:", ["A level premium that's set when the policy is issued", "A cash value that's guaranteed in the policy", "A face amount that rises and falls with the stock market", "Coverage that lasts for the insured's whole life"], "C", "A death benefit tied to investments describes variable life. Whole life's face amount and cash value are guaranteed.");
  mc("L133", "L4", "An endowment policy matures when:", ["The insured dies, since endowments pay only at death", "The insured reaches 65, the maturity age for every endowment", "The policy has been in force long enough to pass the 7-pay test", "The cash value equals the face amount on the maturity date"], "D", "An endowment matures at a set date or age, such as 20 years or age 65, when the cash value reaches the face amount. If the insured dies first, the face amount is paid then.");
  mc("L134", "L4", "For the same insured and face amount, which policy builds cash value the fastest?", ["Straight whole life", "20-pay life", "20-year endowment", "Life paid up at 65"], "C", "A 20-year endowment's cash value must equal the face amount in 20 years. A 20-pay life policy finishes premiums in 20 years but doesn't endow until age 100 (or 121).");
  mc("L135", "L4", "A single premium whole life policy:", ["Is paid up at once and has cash value right away", "Has no cash value until the 10th year", "Requires premiums until age 65", "Can't be surrendered"], "A", "One payment buys a paid-up policy with immediate cash value. Funding it that fast usually makes it a modified endowment contract (MEC).");
  mc("L136", "L4", "A whole life policy whose premium increases each year for the first 5 to 10 years and then stays level is a:", ["Modified premium policy", "Graded premium policy", "Indeterminate premium policy", "Single premium policy"], "B", "Graded premium rises gradually each year before leveling off. Modified premium makes one step up after a few years.");
  mc("L137", "L4", "An indeterminate premium (nonguaranteed premium) policy:", ["Guarantees a level premium that can never change for the life of the policy", "Lets the owner skip or change premiums at will, like universal life", "Is paid with one premium, with the amount set when the policy is issued", "Guarantees a maximum premium but charges a lower current premium that can change"], "D", "The insurer charges a current premium based on its experience and can change it, but never above the guaranteed maximum in the policy.");
  mc("L138", "L4", "Which policy lets the owner change the face amount, the premium and the premium-paying period, moving between term and permanent forms as needs change?", ["Adjustable life", "Modified whole life", "Limited-pay life", "Industrial life"], "A", "Adjustable life can be reshaped over time. Raising the face amount usually requires evidence of insurability.");
  mc("L139", "L4", "An adjustable life policyowner wants to increase the face amount. The insurer will usually require:", ["Nothing; increases are automatic", "Evidence of insurability", "A separate new policy", "Conversion to term first"], "B", "Lowering coverage is easy, but an increase adds risk, so the insurer usually asks for proof of insurability.");
  mc("L140", "L4", "A double protection policy pays twice the face amount if the insured dies:", ["In an accident at any age, because it includes an accidental death benefit", "After age 65, because the term portion begins when premiums stop", "Before a set age, because it combines whole life with an equal amount of term", "From any cause after the policy is paid up, because dividends double it"], "C", "Double protection adds term equal to the whole life face amount until a set age. After the term ends, only the whole life amount is paid. Don't confuse it with double indemnity, which pays extra for accidental death.");
  mc("L141", "L4", "A family policy usually provides:", ["Whole life on the primary insured and term coverage on the spouse and children", "Whole life on every family member, with equal face amounts for each", "Term coverage on the primary insured and whole life on the children", "Group coverage for the family through the primary insured's employer"], "A", "The breadwinner gets permanent coverage; the spouse and children get term, which the children can usually convert later without proving insurability.");
  mc("L142", "L4", "Under a family policy or children's term rider, a child born after the policy is issued is usually:", ["Excluded until age 5, then added with a higher premium for each child", "Covered automatically, often from about 15 days old, with no premium increase", "Covered only after a medical exam and an added premium for that child", "Covered only if the child was named on the original application"], "B", "Newborns are added automatically, and the premium doesn't change with the number of children.");
  mc("L143", "L4", "A joint life policy insuring two business partners pays the death benefit:", ["At the second death, and then the policy ends", "At each death, so it pays twice in total", "Only if both partners die in the same accident", "At the first death, and then the policy ends"], "D", "Joint life is first-to-die: it pays once, at the first death. Survivorship life pays at the second death.");
  mc("L144", "L4", "Compared with buying two separate whole life policies on the same two people, a joint life (first-to-die) policy usually has:", ["A higher premium than the two policies combined", "A lower premium than the two policies combined", "No cash value, because it's a form of term", "Coverage that's limited to married couples"], "B", "It pays only once, so it costs less than two separate policies. It can insure any two people with insurable interest, such as business partners.");
  mc("L145", "L4", "A wealthy married couple wants money to pay estate taxes, which will be due after both of them have died. The best fit is:", ["Joint life (first-to-die)", "Two decreasing term policies", "Survivorship (second-to-die) life", "A family policy"], "C", "Survivorship life pays at the second death, when estate taxes are usually due. Its premium is lower than joint life because the payout comes later.");
  mc("L146", "L4", "A small final expense policy, issued with little or no underwriting, pays only a return of premiums plus interest if the insured dies of an illness in the first two years. This is a:", ["Graded death benefit policy", "Jumping juvenile policy", "Double protection policy", "Modified endowment contract"], "A", "Limited benefit policies restrict what they pay. A graded death benefit pays a reduced amount for deaths from illness in the early years; accidental death is usually covered in full from the start.");
  mc("L147", "L4", "In a universal life policy, which values are guaranteed?", ["The current interest rate", "A minimum interest rate and maximum mortality charges", "The death benefit no matter how much premium is paid", "The cash value at age 65"], "B", "Universal life credits a current rate that can change, but it guarantees a minimum interest rate and caps the mortality (cost of insurance) charges.");
  mc("L148", "L4", "A universal life policyowner skips several premium payments. The policy:", ["Lapses at the end of the grace period after the first missed premium", "Converts to extended term coverage for as long as the cash value lasts", "Stays in force as long as the cash value covers the monthly deductions", "Becomes a modified endowment contract and loses its tax advantages"], "C", "Premiums are flexible. The monthly mortality and expense charges come out of the cash value; the policy lapses only if the cash value can't cover them.");
  mc("L149", "L4", "Under universal life death benefit Option A (level), as the cash value grows, the pure insurance (net amount at risk):", ["Increases", "Stays the same", "Is eliminated after 10 years", "Decreases"], "D", "With a level death benefit, a larger cash value means less pure insurance. Option B keeps the net amount at risk level because it pays the face amount plus the cash value.");
  mc("L150", "L4", "Universal life policies must keep a corridor of insurance so that:", ["The insurer can raise premiums whenever the cash value grows too slowly", "It keeps enough pure insurance above the cash value to qualify as life insurance for taxes", "The owner can borrow against the cash value without paying interest", "Dividends on the policy are guaranteed for as long as it stays in force"], "B", "If the cash value gets too close to the death benefit, the policy would lose its tax treatment as life insurance, so the death benefit must stay a set amount above the cash value.");
  mc("L151", "L4", "Interest-sensitive (current assumption) whole life differs from traditional whole life because:", ["Its premium or cash value reflects current interest and mortality, while the face stays fixed", "Its premium is fully flexible, so the owner can pay any amount at any time", "It has no cash value, so all of the premium pays for pure protection", "It's a variable product, so selling it requires FINRA registration"], "A", "Current assumption whole life keeps a fixed face amount but passes better (or worse) interest and mortality results to the owner through the premium or cash value.");
  mc("L152", "L4", "If interest rates rise, the owner of an interest-sensitive whole life policy may be able to:", ["Skip premiums with no effect", "Raise the death benefit without limit", "Pay a lower premium or build cash value faster", "Move money into separate accounts"], "C", "Higher credited interest can lower the premium or speed cash value growth. If rates fall, the premium can go up, but not above the guaranteed maximum.");
  mc("L153", "L4", "Which is true of fixed-premium variable life insurance?", ["It guarantees a minimum death benefit (the face amount), but not the cash value", "It guarantees the cash value, but the death benefit can fall below the face", "The insurer bears the investment risk on the separate account", "It can be sold by anyone who holds a life insurance license alone"], "A", "Variable life invests through separate accounts, so the owner bears the investment risk on the cash value. Selling it also requires FINRA registration.");
  mc("L154", "L4", "Variable universal life combines:", ["The level premiums of whole life and the low cost of decreasing term", "The fixed interest of universal life and the guaranteed cash value of whole life", "Group term coverage with an individual whole life conversion right", "The flexible premiums of universal life and the investment choices of variable life"], "D", "Variable universal life has flexible premiums and an adjustable death benefit, with cash value in separate-account investments chosen by the owner.");
  mc("L155", "L4", "All of these are types of term insurance EXCEPT:", ["Level term", "Limited-pay life", "Decreasing term", "Annually renewable term"], "B", "Limited-pay life is permanent (whole life) coverage with premiums that stop early.");
  mc("L156", "L4", "Adding a 10-year level term rider to a whole life policy is a way to:", ["Build the cash value faster than the base policy alone", "Waive the premiums if the insured becomes disabled", "Add temporary coverage for less than buying more whole life", "Guarantee the right to buy more coverage later"], "C", "A term rider adds extra protection for a set time, such as while children are young, at a low cost.");
  mc("L157", "L4", "A “life paid up at 65” policy:", ["Expires at 65 unless it's renewed or converted", "Pays the face amount to the insured at age 65", "Is term coverage that ends when premiums stop", "Requires premiums until 65 and keeps coverage for life"], "D", "It's limited-pay whole life: premiums stop at 65, and coverage continues until death or maturity.");

  // Annuities (L7)
  mc("L158", "L7", "The annuity principle is best described as:", ["Building an estate that's paid to heirs at the owner's death", "Paying out a sum of money through payments that can last for life", "Pooling premiums to pay members' medical bills as they occur", "Transferring the risk of property loss to an insurer"], "B", "Life insurance creates an estate when the insured dies. An annuity does the opposite: it scientifically liquidates a sum through regular payments.");
  mc("L159", "L7", "Annuities pool mortality: annuitants who die early help fund those who live longer. That's why a straight life annuity:", ["Can pay more each month than interest alone, for as long as the annuitant lives", "Always refunds any unused premium to a beneficiary at death", "Pays the same monthly amount no matter the annuitant's age", "Requires a medical exam to set the size of each payment"], "A", "Each payment is part principal, part interest, plus a share of the money left by annuitants who died early. Older annuitants get larger payments for the same premium.");
  mc("L160", "L7", "A flexible premium deferred annuity allows:", ["Only one payment, made when the contract is issued", "Income payments that begin within 12 months", "Payments of varying amounts at varying times", "No withdrawals until the owner reaches age 65"], "C", "The owner can add money when and in the amounts they choose during the accumulation period.");
  mc("L161", "L7", "Ken puts $100,000 into a single premium deferred annuity at 55 and plans to start income at 65. During those 10 years, the money:", ["Pays him monthly income", "Grows tax-deferred", "Is taxed each year as income", "Can't earn interest"], "B", "During the accumulation period, earnings grow tax-deferred. They're taxed when withdrawn or paid out.");
  mc("L162", "L7", "An immediate annuity can only be bought with:", ["Monthly premiums", "Flexible premiums", "Payroll deduction", "A single premium"], "D", "An immediate annuity starts paying within 12 months, so it must be funded with one lump sum.");
  mc("L163", "L7", "In a fixed annuity, who bears the investment risk?", ["The annuitant", "The owner's beneficiary", "The insurer", "FINRA"], "C", "A fixed annuity guarantees principal and a minimum interest rate, so the insurer carries the risk. In a variable annuity, the owner does.");
  mc("L164", "L7", "During the accumulation period, a variable annuity owner's share of the separate account is measured in:", ["Annuity units", "Paid-up additions", "Accumulation units", "Dividends"], "C", "Payments buy accumulation units whose value changes with the investments. At payout they're converted to annuity units.");
  mc("L165", "L7", "When a variable annuity is annuitized, the accumulation units are converted to:", ["Annuity units, whose number stays fixed while their value changes", "Accumulation units, whose value is fixed once payments begin", "Fixed-dollar payments guaranteed for the annuitant's life", "Cash dividends paid from the insurer's general account"], "A", "The annuitant receives the value of a fixed number of annuity units each period, so the payment rises and falls with the investments.");
  mc("L166", "L7", "An equity-indexed annuity typically guarantees:", ["The full return of the index each year, with no cap on interest credited", "No minimum return, since the owner bears all of the investment risk", "Returns equal to a stock mutual fund the owner chooses", "A minimum interest rate, plus index-linked interest subject to caps or participation rates"], "D", "Indexed annuities are fixed products: principal and a minimum rate are guaranteed, and extra interest follows an index such as the S&P 500, up to limits.");
  mc("L167", "L7", "The owner of a deferred annuity dies before income payments begin. The beneficiary generally receives:", ["Nothing, because no income payments had started yet", "The greater of the premiums paid or the accumulated value", "Only the interest earned, with the premiums kept by the insurer", "Life income figured on the owner's age at death"], "B", "Before the annuity starting date, the contract guarantees a death benefit, usually the higher of what was paid in or the current value.");
  mc("L168", "L7", "An owner who cashes in a deferred annuity in its early years will usually pay a:", ["Surrender charge", "Corridor fee", "Mortality charge", "Dividend load"], "A", "Surrender charges are a back-end load that usually shrinks each year and disappears after a set number of years.");
  mc("L169", "L7", "A joint life annuity (not joint and survivor) covering two people:", ["Pays until the second death", "Pays a lump sum at the second death", "Stops at the first death", "Guarantees 10 years of payments"], "C", "Joint life stops paying when the first annuitant dies. Joint and survivor keeps paying until the second death.");
  mc("L170", "L7", "Under a joint and two-thirds survivor annuity:", ["The survivor receives two-thirds of the original payment after the first death", "Each annuitant receives two-thirds of the payment while both are alive", "Payments stop at the first death, and two-thirds of the balance is refunded", "The survivor receives the full payment, and two-thirds goes to an heir"], "A", "Payments continue for the survivor's life at a reduced amount, here two-thirds. A smaller survivor share means a larger payment while both are alive.");
  mc("L171", "L7", "Under an installment refund annuity, if the annuitant dies before receiving as much as they paid in, the beneficiary receives:", ["A lump sum equal to the difference, paid right away", "Payments for a fixed 10 years, whatever was paid in", "Double payments until the remaining balance is used up", "Continued payments until the full amount paid in has been returned"], "D", "Installment refund keeps the payments going to the beneficiary. Cash refund pays the difference in a lump sum.");
  mc("L172", "L7", "For the same premium, which payout option gives a 65-year-old annuitant the smallest monthly payment?", ["Straight life", "Life with 5-year period certain", "Life with 10-year period certain", "Life with 20-year period certain"], "D", "The longer the guarantee, the lower each payment. Straight life, with no guarantee, pays the most.");
  mc("L173", "L7", "Each income payment from a non-qualified annuity is:", ["Partly a tax-free return of the owner's cost basis, with the rest taxed as income", "Fully taxable as a capital gain in the year it's received", "Fully tax-free, because the premiums were paid with after-tax money", "Taxed only on the part paid after the annuitant turns 70"], "A", "The exclusion ratio spreads the after-tax investment over the expected payments, so part of each payment is tax-free until the basis is recovered.", "irc72");

  // Policy provisions, options and other features (L5)
  mc("L174", "L5", "The insuring clause (insuring agreement) of a life policy:", ["Lists the premium amounts and how often they can be paid", "States the insurer's promise to pay the death benefit when the insured dies", "Names the agent and the agency that sold the policy", "Sets how long the owner has to return the policy for a refund"], "B", "The insuring clause is the insurer's basic promise to pay, usually on the policy's first page.");
  mc("L175", "L5", "When the owner and the insured are different people, which right belongs to the policyowner?", ["Naming and changing the beneficiary", "Receiving the death benefit", "Approving every claim", "Setting the premium rate"], "A", "The owner controls the policy: naming beneficiaries, taking loans, assigning it and choosing options. The insured is just the person whose life is covered.");
  mc("L176", "L5", "The free look provision lets the policyowner:", ["Skip one premium each year without the policy lapsing or losing value", "Change the beneficiary at any time without notifying the insurer", "Return the policy within a set time after delivery for a full refund", "Borrow against the cash value for one year without paying interest"], "C", "The free look period starts when the policy is delivered. Its length is set by state law and the policy.");
  mc("L177", "L5", "To reinstate a lapsed life policy, the owner usually must do all of these EXCEPT:", ["Apply within the reinstatement period", "Provide evidence of insurability", "Pay overdue premiums with interest", "Pay a new commission to the agent"], "D", "Reinstatement typically requires a timely application, proof of insurability, past-due premiums with interest, and repaying or reinstating any loan. No new commission is involved.");
  mc("L178", "L5", "Why might reinstating a lapsed policy be better than buying a new one?", ["It keeps the original issue age, values and terms, so the premium stays lower", "No back premiums or interest are owed when the policy is reinstated", "No evidence of insurability is needed, even years after the lapse", "The policy can never again be contested for any misstatement"], "A", "Reinstatement restores the old policy at its original age and terms, which a new policy at an older age can't match.");
  mc("L179", "L5", "When a life policy is reinstated, the incontestable period:", ["No longer applies, since the original period already ended", "Starts over for statements made in the reinstatement application", "Is extended to 5 years for the whole original application", "Is waived permanently once the back premiums are paid"], "B", "The insurer gets a new contestable period, but only for misstatements in the reinstatement application.");
  mc("L180", "L5", "A policyowner wants to switch a whole life policy to a 20-pay life policy with the same insurer. The provision that allows this is the:", ["Reinstatement provision", "Change of plan provision", "Entire contract provision", "Assignment provision"], "B", "A change of plan lets the owner exchange the policy for another type. A move to a plan with more pure insurance usually needs evidence of insurability.");
  mc("L181", "L5", "Under an excess interest provision, interest credited above the guaranteed rate:", ["Is paid to the agent as part of the renewal commission", "Becomes the new guaranteed rate for the life of the policy", "Goes to the cash value or lowers premiums, but isn't guaranteed", "Is paid out each year as a taxable cash dividend"], "C", "The insurer shares interest earned above the guaranteed minimum, but the extra rate can change.");
  mc("L182", "L5", "A universal life owner takes a partial withdrawal (not a loan) of cash value. Which is true?", ["It must be repaid with interest or the policy will lapse", "It's treated as a loan and deducted only from the death claim", "It's allowed only after the policy has been in force for 10 years", "It reduces the cash value and the death benefit and isn't repaid like a loan"], "D", "A withdrawal permanently takes money out. A loan, by contrast, accrues interest and can be repaid.");
  mc("L183", "L5", "An other-insured (spouse) rider on a whole life policy usually provides:", ["Level term coverage on the spouse, often convertible", "Whole life coverage on the spouse at no charge", "Waiver of premium for the spouse", "Disability income for the spouse"], "A", "Other-insured riders add term coverage on a spouse or children to the main policy at a lower cost than a separate policy.");
  mc("L184", "L5", "A typical aviation exclusion in a life policy may exclude death:", ["As a fare-paying passenger on a scheduled airline", "As a pilot or crew member, or in a military or private aircraft", "In a car accident", "During any travel outside the U.S."], "B", "Fare-paying passengers on commercial airlines are normally covered. The exclusion targets pilots, crew and noncommercial flying.");
  mc("L185", "L5", "A soldier's policy has a status-type war exclusion. The soldier dies in a car accident at home while on leave. The insurer:", ["Pays the full face amount, because war didn't cause the death", "Pays double the face amount, because the death was accidental", "Refunds premiums only, because death occurred during military service", "Pays the cash value plus interest, but not the face amount"], "C", "Status type excludes any death while in military service, whatever the cause. Under a results-type clause, this car accident death would be paid.");
  mc("L186", "L5", "Under a standard 2-year suicide clause, an insured dies by suicide 3 years after the policy was issued. The insurer:", ["Pays the full face amount", "Refunds premiums only", "Pays nothing", "Pays half the face amount"], "A", "After the suicide period ends, suicide is covered like any other cause of death.");
  mc("L187", "L5", "Nonforfeiture values exist because:", ["Term policies build cash value that must be returned when they expire", "Insurers must pay dividends to owners who stop paying premiums", "The agent guarantees a minimum value for every policy sold", "The owner keeps a right to a permanent policy's cash value if premiums stop"], "D", "State nonforfeiture laws make sure the owner doesn't lose the built-up value of a permanent policy when it lapses.");
  mc("L188", "L5", "Pat stops paying premiums on a whole life policy and wants coverage for life with no more premiums. Pat should choose:", ["Extended term", "Reduced paid-up", "Cash surrender", "The one-year term dividend option"], "B", "Reduced paid-up keeps lifetime coverage at a smaller face amount. Extended term keeps the full face amount, but only for a limited time.");
  mc("L189", "L5", "The insured dies with a policy loan still unpaid. The loan balance is:", ["Paid off by the insurer as a bonus", "Owed by the beneficiary personally", "Subtracted from the death benefit", "Forgiven"], "C", "Any outstanding loan plus interest is deducted from the proceeds before they're paid.");
  mc("L190", "L5", "A policy loan provision with a variable interest rate means the rate:", ["Is fixed in the policy and can never change while the loan is open", "Is set by the agent each time the owner applies for a loan", "Is zero, since the owner is borrowing their own cash value", "Can change periodically, tied to a published index, within legal limits"], "D", "Loan rates are either fixed (stated in the policy) or variable (adjusted periodically against an index).");
  mc("L191", "L5", "Policy dividends on a participating policy are best described as:", ["A return of excess premium that isn't guaranteed and generally isn't taxable", "Taxable income in the year they're paid, like stock dividends", "Guaranteed interest that the insurer must pay every year", "A rebate of part of the agent's commission to the owner"], "A", "Dividends return part of the premium when the insurer's results are better than expected. They're not taxable until they exceed the premiums paid.");
  mc("L192", "L5", "Under the accumulate-at-interest dividend option, which part is taxable?", ["The dividends", "The interest earned on the dividends", "Both the dividends and the interest", "Neither"], "B", "The dividends themselves are a return of premium, but the interest they earn is taxable income.");
  mc("L193", "L5", "The policyowner didn't choose a settlement option before the insured died. Who can choose one?", ["No one; it must be paid in a lump sum", "The agent", "The insured's employer", "The beneficiary"], "D", "If the owner didn't elect an option, the beneficiary can choose how to receive the proceeds.");
  mc("L194", "L5", "Sam names his three children as beneficiaries “per stirpes.” One child dies before Sam, leaving two kids. At Sam's death, that child's share goes to:", ["The two surviving children, who split it equally", "Sam's estate, to be paid out under his will", "The deceased child's spouse, as next of kin", "The deceased child's two kids, who split that share"], "D", "Per stirpes passes a deceased beneficiary's share down to their descendants. Per capita splits it among the surviving named beneficiaries.");
  mc("L195", "L5", "Under a per capita designation, if one of three named beneficiaries dies before the insured, the proceeds are:", ["Split equally among the surviving named beneficiaries", "Paid to the deceased beneficiary's children", "Paid to the insured's estate", "Held by the insurer"], "A", "Per capita means “by the head”: only the living named beneficiaries share.");
  mc("L196", "L5", "Naming “my children” as beneficiary, rather than naming each child, is a:", ["Revocable designation", "Contingent designation", "Class designation", "Estate designation"], "C", "A class designation covers a group, which can include children born or adopted later.");
  mc("L197", "L5", "When the insured's estate receives the proceeds, because it's named or no beneficiary survives, the money:", ["Goes through probate and may be reached by the insured's creditors", "Is always free of estate tax because it's life insurance", "Is paid to the agent to hold until heirs are found", "Goes straight to the state as unclaimed property"], "A", "Paying a named person avoids probate. Paying the estate exposes the proceeds to probate delays and creditors.");
  mc("L198", "L5", "Insurers generally won't pay large proceeds directly to a minor. A common solution is:", ["Paying the agent to hold the money until the child is an adult", "Naming a trust, guardian or custodian to receive it for the child", "Holding the money until the minor turns 30, with no interest", "Paying the child's school directly for tuition and fees"], "B", "Minors can't sign a valid release, so the money goes to a trust, a court-appointed guardian or a custodian.");
  mc("L199", "L5", "Under the filing (recording) method, a beneficiary change takes effect when:", ["The insurer receives and records written notice; the policy isn't returned", "The policy is sent back to the insurer and the change is written on it", "The current beneficiary signs a form agreeing to the change", "The agent approves the change and notes it in the client file"], "A", "The filing method is the most common. The endorsement method requires sending the policy in so the change can be written on it.");
  mc("L200", "L5", "With an irrevocable beneficiary, the owner needs the beneficiary's consent to:", ["Pay the premium", "Update their own mailing address", "Take a policy loan or assign the policy", "Read the policy"], "C", "An irrevocable beneficiary has a vested interest, so the owner can't change them, borrow against the policy or assign it without consent.");
  mc("L201", "L5", "Paying premiums annually instead of monthly usually costs:", ["More in total, because the insurer must wait longer for its money", "Exactly the same, since state law requires equal total premiums", "Nothing extra in the first year, then the same as monthly", "Less in total, since the insurer has the money sooner and bills less"], "D", "More frequent modes add a charge for lost interest and billing costs.");
  mc("L202", "L5", "A universal life policy that charges a fee when the owner surrenders it in the early years has a:", ["Front-end load, taken from each premium as it's paid", "Back-end load, also called a surrender charge", "Corridor charge, based on the pure insurance", "Mortality charge, based on the insured's age"], "B", "A front-end load is taken from each premium as it's paid. A back-end load is charged when the policy is surrendered.");
  mc("L203", "L5", "Most accidental death riders pay only if death occurs within how many days of the accident?", ["30 days", "60 days", "90 days", "180 days"], "C", "Death must usually happen within 90 days of the accident, and often before a set age, such as 60 to 70.");
  mc("L204", "L5", "Under a waiver of premium rider, premiums are waived once the insured has been totally disabled for a waiting period of usually:", ["30 days", "90 days", "6 months", "1 year"], "C", "Premiums paid during the 6-month waiting period are typically refunded if the disability continues. The disability usually must begin before a set age, such as 60 or 65.");
  mc("L205", "L5", "In universal life, the rider that covers the monthly cost of insurance and expense charges while the insured is disabled is:", ["Waiver of monthly deduction", "Payor benefit", "Cost of living", "Guaranteed insurability"], "A", "It pays only the monthly deductions, not the full planned premium, so the cash value doesn't grow from it.");
  mc("L206", "L5", "A cost of living rider on a life policy:", ["Lowers the premium each year as the cost of living rises", "Raises the face amount with inflation, often tied to the CPI", "Pays monthly income that rises with inflation during disability", "Raises the policy's dividends to match changes in the CPI"], "B", "The rider usually adds increasing term coverage so the death benefit keeps up with inflation.");

  // Other life topics on the outline
  mc("L207", "L6", "Which cost comparison method takes the time value of money into account?", ["Traditional net cost method", "Interest-adjusted net cost method", "Loading method", "Net single premium method"], "B", "The interest-adjusted method, used in buyer's guide cost indexes, accounts for interest the money could have earned.");
  mc("L208", "L6", "The traditional net cost method of comparing policies:", ["Subtracts dividends and cash value from premiums, ignoring interest", "Discounts every payment using a 5% interest assumption", "Compares only the death benefits, not the premiums", "Is the method used for buyer's guide cost indexes"], "A", "Because it ignores interest, the traditional method can make a policy look cheaper than it is. That's why the interest-adjusted method is preferred.");
  mc("L209", "L8", "A 401(k) plan lets employees:", ["Get group life and health coverage at no cost through the plan", "Borrow against future Social Security retirement benefits", "Defer part of their salary before taxes, often with an employer match", "Contribute any amount of after-tax money with no annual limit"], "C", "A 401(k) is a qualified plan funded by salary deferrals, within annual limits. Employers often match part of what employees put in.");
});
